p=root/'src/App.jsx'; s=p.read_text(); s=s.replace('import FullStackScenarios from "./pages/FullStackScenarios";','import FullStackScenarios from "./pages/FullStackScenarios";\nimport PracticalLabs from "./pages/PracticalLabs";'); s=s.replace(': view === "scenarios" ? <FullStackScenarios /> : <Questions', ': view === "scenarios" ? <FullStackScenarios /> : view === "labs" ? <PracticalLabs /> : <Questions'); p.write_text(s)

