p=root/'src/components/Sidebar.jsx'; s=p.read_text(); s=s.replace('import { questions } from "../data/index";','import { questions } from "../data/index";\nimport { buildLabs } from "../data/buildLabs";\nimport { debugLabs } from "../data/debugLabs";\nimport { architectureLabs } from "../data/architectureLabs";'); marker='''          <div className="side-label section-label fullstack-label">FULL STACK</div>'''; insert='''          <div className="side-label section-label practical-label">PRACTICAL ENGINEERING</div>\n          <nav className="topic-nav">\n            <button className={view === "labs" ? "nav-item active" : "nav-item"} onClick={() => go("labs")}>\n              <span>🛠</span><label>Build / Debug Labs</label><small>{buildLabs.length + debugLabs.length + architectureLabs.length}</small>\n            </button>\n          </nav>\n\n'''; s=s.replace(marker,insert+marker); p.write_text(s)

