p=root/'src/components/Header.jsx'; s=p.read_text(); s=s.replace('import { fullStackScenarios } from "../data/fullstackScenarios";','import { fullStackScenarios } from "../data/fullstackScenarios";\nimport { buildLabs } from "../data/buildLabs";\nimport { debugLabs } from "../data/debugLabs";\nimport { architectureLabs } from "../data/architectureLabs";'); s=s.replace('const scenarios = view === "scenarios";','const scenarios = view === "scenarios";\n  const labs = view === "labs";'); s=s.replace(': scenarios ? "Full-Stack Scenarios" : "Backend Interview Preparation";', ': scenarios ? "Full-Stack Scenarios" : labs ? "Practical Engineering Labs" : "Backend Interview Preparation";'); s=s.replace('''            : scenarios\n            ? "Production debugging · Architecture · Security · Reliability · Performance · Full-stack system thinking"\n            : "Java · Spring Boot · Microservices · SQL · JPA · Security · Cloud · System Design";''','''            : scenarios\n            ? "Production debugging · Architecture · Security · Reliability · Performance · Full-stack system thinking"\n            : labs\n              ? "Build real features · Debug failures · Evolve architecture · Explain engineering trade-offs"\n              : "Java · Spring Boot · Microservices · SQL · JPA · Security · Cloud · System Design";'''); s=s.replace('''    : fullstack ? `${fullStackLessons.length} FULL STACK LESSONS` : scenarios ? `${fullStackScenarios.length} SCENARIOS` : `${questions.length} QUESTIONS`;''','''    : fullstack ? `${fullStackLessons.length} FULL STACK LESSONS` : scenarios ? `${fullStackScenarios.length} SCENARIOS` : labs ? `${buildLabs.length + debugLabs.length + architectureLabs.length} LABS` : `${questions.length} QUESTIONS`;'''); s=s.replace(''' : fullstack ? "fullstack@learning:~" : scenarios ? "production@scenarios:~" : "backend@interview:~"}''',''' : fullstack ? "fullstack@learning:~" : scenarios ? "production@scenarios:~" : labs ? "engineering@labs:~" : "backend@interview:~"}'''); p.write_text(s)

